/**
 * JUAN PABLO — INTERACTIVE 3D HERO
 * Exact GLB Model Loader (assets/models/happy-face.glb)
 * Ueno Iconic Gunmetal Dark-Chrome / Liquid Steel Materiality
 * Y-Axis Rotation Driven by Top-to-Bottom Vertical Cursor Movement with Inertia
 */

(function () {
  'use strict';

  const HAPPY_FACE_GLB_BASE64 = "";

  function base64ToArrayBuffer(base64) {
    const binaryString = window.atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
  }

  // Generates studio environment map reproducing the Ueno high-contrast lighting
  function createUenoStudioEnvironment(renderer) {
    if (typeof THREE.PMREMGenerator === 'undefined') return null;

    const pmrem = new THREE.PMREMGenerator(renderer);
    pmrem.compileEquirectangularShader();

    const canvas = document.createElement('canvas');
    canvas.width = 1024;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');

    // 1. Deep black studio void
    ctx.fillStyle = '#060709';
    ctx.fillRect(0, 0, 1024, 512);

    // 2. Large high-intensity Top-Left Key Softbox (Matches the bright specular dome hotspot)
    const keySoftbox = ctx.createRadialGradient(280, 120, 10, 280, 120, 260);
    keySoftbox.addColorStop(0, '#ffffff');
    keySoftbox.addColorStop(0.3, '#ffffff');
    keySoftbox.addColorStop(0.65, 'rgba(230, 235, 245, 0.6)');
    keySoftbox.addColorStop(1, 'rgba(200, 210, 225, 0)');
    ctx.fillStyle = keySoftbox;
    ctx.fillRect(0, 0, 600, 360);

    // 3. Sharp Rim Accent Strip (Upper Right)
    const rightRim = ctx.createLinearGradient(780, 0, 880, 0);
    rightRim.addColorStop(0, 'rgba(255, 255, 255, 0)');
    rightRim.addColorStop(0.5, '#ffffff');
    rightRim.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = rightRim;
    ctx.fillRect(780, 40, 100, 380);

    // 4. Subtle bottom reflective bounce
    const bottomBounce = ctx.createRadialGradient(512, 440, 20, 512, 440, 220);
    bottomBounce.addColorStop(0, 'rgba(180, 195, 215, 0.45)');
    bottomBounce.addColorStop(1, 'rgba(10, 12, 16, 0)');
    ctx.fillStyle = bottomBounce;
    ctx.fillRect(200, 300, 624, 212);

    const texture = new THREE.CanvasTexture(canvas);
    texture.mapping = THREE.EquirectangularReflectionMapping;
    const envMap = pmrem.fromEquirectangular(texture).texture;
    pmrem.dispose();
    texture.dispose();

    return envMap;
  }

  // Ueno Signature Gunmetal Dark-Chrome Material
  function createUenoChromeMaterial() {
    return new THREE.MeshPhysicalMaterial({
      color: 0x16181d,          // Deep dark gunmetal / obsidian steel base
      metalness: 0.94,         // High metallic conduction
      roughness: 0.20,         // Satin metallic surface diffusion for glowing hot spot
      clearcoat: 1.0,          // Razor-sharp outer lacquer for bevel and edge glints
      clearcoatRoughness: 0.03,// Mirror-like clearcoat speculars
      reflectivity: 1.0,
      envMapIntensity: 2.6,    // High contrast reflection response
      side: THREE.DoubleSided
    });
  }

  function initSmiley3D() {
    const container = document.getElementById('smiley-3d-wrapper');
    const canvas = document.getElementById('smiley-3d-canvas');
    if (!container || !canvas || typeof THREE === 'undefined') return;

    // 1. Scene Setup
    const scene = new THREE.Scene();

    const fov = 42;
    function getContainerSize() {
      if (window.innerWidth < 900 && container) {
        const rect = container.getBoundingClientRect();
        return {
          w: rect.width || window.innerWidth,
          h: rect.height || (window.innerHeight * 0.42)
        };
      }
      return {
        w: window.innerWidth || document.documentElement.clientWidth || 1200,
        h: window.innerHeight || document.documentElement.clientHeight || 800
      };
    }

    let size = getContainerSize();
    const camera = new THREE.PerspectiveCamera(fov, size.w / size.h, 0.1, 100);

    function getOptimalCameraZ() {
      if (window.innerWidth < 768) return 7.2;
      if (window.innerWidth < 1200) return 7.4;
      return 6.6;
    }
    camera.position.set(0, 0, getOptimalCameraZ());

    const renderer = new THREE.WebGLRenderer({
      canvas: canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'high-performance'
    });
    renderer.setSize(size.w, size.h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);

    if (renderer.outputColorSpace) {
      renderer.outputColorSpace = THREE.SRGBColorSpace;
    } else if (renderer.outputEncoding) {
      renderer.outputEncoding = THREE.sRGBEncoding;
    }
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.18;

    // Attach Ueno Dark Studio Environment Map
    const studioEnv = createUenoStudioEnvironment(renderer);
    if (studioEnv) {
      scene.environment = studioEnv;
    }

    // 2. Transformation Hierarchies
    const smileyGroup = new THREE.Group();
    scene.add(smileyGroup);

    const innerGroup = new THREE.Group();
    smileyGroup.add(innerGroup);

    const modelGroup = new THREE.Group();
    innerGroup.add(modelGroup);

    // 3. Iconic Ueno Studio Lighting Setup
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.18);
    scene.add(ambientLight);

    const hemiLight = new THREE.HemisphereLight(0xffffff, 0x111116, 0.35);
    hemiLight.position.set(0, 10, 0);
    scene.add(hemiLight);

    const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
    keyLight.position.set(-3.8, 4.8, 4.2);
    scene.add(keyLight);

    const frontKey = new THREE.DirectionalLight(0xffffff, 1.8);
    frontKey.position.set(-1.5, 2.5, 5.0);
    scene.add(frontKey);

    const rimLight = new THREE.DirectionalLight(0xffffff, 2.4);
    rimLight.position.set(4.5, -1.0, -2.5);
    scene.add(rimLight);

    const topRim = new THREE.DirectionalLight(0xffffff, 1.6);
    topRim.position.set(1.0, 5.0, -3.5);
    scene.add(topRim);

    const fillLight = new THREE.DirectionalLight(0xccdcf5, 0.65);
    fillLight.position.set(3.5, -4.0, 2.5);
    scene.add(fillLight);

    let baseMaxDim = 1.0;

    function getTargetDimension() {
      if (window.innerWidth < 900) {
        return 4.7; // Another +30% zoomed scale on mobile/tablets
      }
      return 2.84; // Standard desktop scale
    }

    function updateModelScale() {
      if (!modelGroup) return;
      const targetDim = getTargetDimension();
      const currentScale = targetDim / baseMaxDim;
      modelGroup.scale.set(currentScale, currentScale, currentScale);
    }

    // Compute X position so the distance from the left screen edge to the 3D face
    // matches the exact distance from the right screen edge to the "¡próximamente!" stage
    function getLeftAlignedX() {
      if (window.innerWidth < 900) {
        return 0; // Centered on mobile / tablets
      }

      const vFOV = (camera.fov * Math.PI) / 180;
      const visibleHeightAtZ0 = 2 * Math.tan(vFOV / 2) * camera.position.z;
      const visibleWidthAtZ0 = visibleHeightAtZ0 * camera.aspect;

      // Find the distance from the right border to the coming soon section
      const stageRight = document.querySelector('.stage-right') || document.querySelector('.comingsoon-block');
      let targetPixelLeft = 0;

      if (stageRight) {
        const rect = stageRight.getBoundingClientRect();
        // Distance from right edge of viewport to the right edge of stage-right content
        const distFromRight = Math.max(0, window.innerWidth - rect.right);
        targetPixelLeft = distFromRight;
      } else {
        const headerLabel = document.querySelector('.static-header-label') || document.querySelector('.header-static-inner');
        targetPixelLeft = headerLabel ? headerLabel.getBoundingClientRect().left : window.innerWidth * 0.035;
      }

      // Convert targetPixelLeft (screen pixel from left) to 3D world coordinates at Z = 0
      const leftBoundaryWorldX = ((targetPixelLeft / window.innerWidth) - 0.5) * visibleWidthAtZ0;
      const targetDimension = getTargetDimension();
      const radius = targetDimension / 2;

      // Position center so the left boundary of the 3D smiley aligns with targetPixelLeft
      return leftBoundaryWorldX + radius;
    }

    // 4. Model Loading Function
    function setupLoadedModel(rawScene) {
      const bbox = new THREE.Box3().setFromObject(rawScene);
      const center = new THREE.Vector3();
      const dims = new THREE.Vector3();
      bbox.getCenter(center);
      bbox.getSize(dims);

      // Center geometry at origin (0, 0, 0)
      rawScene.position.x = -center.x;
      rawScene.position.y = -center.y;
      rawScene.position.z = -center.z;

      baseMaxDim = Math.max(dims.x, dims.y, dims.z) || 1.0;
      updateModelScale();
      modelGroup.add(rawScene);

      // Apply signature Ueno gunmetal dark-chrome material
      const chromeMaterial = createUenoChromeMaterial();
      rawScene.traverse((child) => {
        if (child.isMesh) {
          child.material = chromeMaterial;
          child.material.needsUpdate = true;
        }
      });
    }

    // Load from embedded Base64 (Instant, 0 latency, 100% reliable even on file:// protocol)
    if (typeof THREE.GLTFLoader !== 'undefined') {
      const loader = new THREE.GLTFLoader();
      try {
        const arrayBuffer = base64ToArrayBuffer(HAPPY_FACE_GLB_BASE64);
        loader.parse(arrayBuffer, '', function (gltf) {
          setupLoadedModel(gltf.scene);
        }, function (err) {
          console.error('Error parsing embedded GLB:', err);
          loader.load('assets/models/happy-face.glb', function (gltf) {
            setupLoadedModel(gltf.scene);
          });
        });
      } catch (e) {
        console.warn('Base64 parse fallback:', e);
        loader.load('assets/models/happy-face.glb', function (gltf) {
          setupLoadedModel(gltf.scene);
        });
      }
    }

    // 5. Clean, Anchored Y-Axis Rotation: Direct 1:1 Static Mapping (0% to 100% = 0° to 360°)
    let targetRotY = 0;

    function onMouseMove(e) {
      // Direct 1:1 static mapping from top (0.0) to bottom (1.0)
      const progress = Math.min(Math.max(e.clientY / window.innerHeight, 0), 1);
      targetRotY = progress * (Math.PI * 2);
    }

    window.addEventListener('mousemove', onMouseMove, { passive: true });

    window.addEventListener('touchstart', (e) => {
      if (e.touches.length > 0) {
        const progress = Math.min(Math.max(e.touches[0].clientY / window.innerHeight, 0), 1);
        targetRotY = progress * (Math.PI * 2);
      }
    }, { passive: true });

    window.addEventListener('touchmove', (e) => {
      if (e.touches.length > 0) {
        const progress = Math.min(Math.max(e.touches[0].clientY / window.innerHeight, 0), 1);
        targetRotY = progress * (Math.PI * 2);
      }
    }, { passive: true });

    // 6. Responsive Resize Handler
    function handleResize() {
      if (!container || !renderer || !camera) return;
      const s = getContainerSize();
      camera.aspect = s.w / s.h;
      camera.position.z = getOptimalCameraZ();
      camera.updateProjectionMatrix();

      updateModelScale();

      renderer.setSize(s.w, s.h);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    handleResize();
    window.addEventListener('resize', handleResize);
    window.addEventListener('load', handleResize);

    // 7. Animation & Render Loop
    let isVisible = true;

    document.addEventListener('visibilitychange', () => {
      isVisible = !document.hidden;
    });

    function animate() {
      requestAnimationFrame(animate);

      if (!isVisible) return;

      // Position anchored to left alignment with juan-pablo*catalán
      const posX = getLeftAlignedX();
      smileyGroup.position.set(posX, 0, 0);
      smileyGroup.rotation.set(0, targetRotY, 0);

      renderer.render(scene, camera);
    }

    animate();
  }

  function start() {
    initSmiley3D();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
